  420: {"description": "A local-history collection about Bannock County, Idaho, and its communities. It pairs with the catalog's other books on southeastern Idaho history.", "cover": "https://pocatellomarket.com/cdn/shop/products/IMG-20190127-113459_1200x1200.jpg?v=1751236270", "source": "https://pocatellomarket.com/products/back-in-time-a-bannock-county-collection"},
